import React, { useReducer, useEffect } from "react";
import axios from "axios";
import Loading from "../Components/Loading";

const init = {
  loading: false,
  err: false,
  data: [],
};

const reducer = (state, { type, payload }) => {
  switch (type) {
    case "FETCH_LOADING":
      return {
        loading: true,
        err: false,
        data: [],
      };

    case "FETCH_SUCCESSFUL":
      return {
        loading: false,
        err: false,
        data: payload,
      };

    case "FETCH_UNSUCCESSFUL":
      return {
        loading: false,
        err: true,
        data: [],
      };
    default:
      throw new Error("Invalid Action type");
  }
};

const url = `https://rctmockapi.onrender.com/teachers`;

const Teachers = () => {
  const [state, dispatch] = useReducer(reducer, init);

  function fetchTeachers() {
    dispatch({ type: "FETCH_LOADING" });
    axios
      .get(url)
      .then((res) => {
        dispatch({ type: "FETCH_SUCCESSFUL", payload: res.data });
      })
      .catch((err) => {
        dispatch({ type: "FETCH_UNSUCCESSFUL" });
        console.log(err);
      });
  }

  const { loading, err, data } = state;

  useEffect(() => {
    fetchTeachers();
  }, []);

  if (loading) {
    return (
      <div className="bg-[#ebecf3] min-h-[600px] p-6 md:p-12">
        <div className="max-w-7xl mx-auto">
          <h1 className="text-3xl md:text-5xl font-extrabold text-center text-[#304b62] mb-8">
            Meet Our Teachers
          </h1>
          <Loading />
        </div>
      </div>
    );
  }

  return (
    <div className="bg-[#ebecf3] min-h-screen py-10 px-4">
      <div className="max-w-5xl mx-auto">
        <h1 className="text-3xl md:text-5xl font-extrabold text-center text-[#304b62] mb-12">
          Meet Our Teachers
        </h1>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
          {data.map((teacher) => (
            <div
              key={teacher.id}
              className="bg-white rounded-2xl p-8 shadow-md flex flex-col items-center text-center transition-transform hover:-translate-y-1 duration-200"
            >
              <div className="w-32 h-32 rounded-full overflow-hidden mb-6 border-4 border-[#d49539] shadow-lg">
                <img
                  src={teacher.avatar}
                  alt={teacher.name}
                  className="w-full h-full object-cover"
                />
              </div>

              <h2 className="text-2xl font-bold text-[#304b62] mb-1">
                {teacher.name}
              </h2>
              <h3 className="text-lg font-semibold text-[#d49539] mb-4">
                {teacher.course}
              </h3>
              <p className="text-base text-slate-600 leading-relaxed max-w-md">
                {teacher.description}
              </p>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default Teachers;
